package com.commercecore.order;import jakarta.persistence.*;import java.util.UUID;@Entity@Table(name="order_item_attributes")public class OrderItemAttribute{@Id@GeneratedValue(strategy=GenerationType.UUID)private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="order_item_id",nullable=false)private OrderItem orderItem;@Column(name="attribute_name",nullable=false,length=80)private String name;@Column(name="attribute_value",nullable=false,length=200)private String value;@Column(name="display_order",nullable=false)private int displayOrder;protected OrderItemAttribute(){}OrderItemAttribute(OrderItem item,String name,String value,int order){this.orderItem=item;this.name=name;this.value=value;this.displayOrder=order;}public UUID getId(){return id;}public String getName(){return name;}public String getValue(){return value;}public int getDisplayOrder(){return displayOrder;}}
